    host.id = 'vorqexa-docs-host';
    host.style.cssText = 'min-height:100%;width:100%;';
    overlay.appendChild(host);
    document.body.appendChild(overlay);

    var shadow = host.attachShadow({mode:'open'});
    var style = document.createElement('style');
    style.textContent = 'html,body{margin:0;padding:0;background:#0b0f0d;color:#e8f3ee;font-family:Inter,ui-sans-serif,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif;} *{box-sizing:border-box;} a,button{touch-action:manipulation;} a[href^="#"]{cursor:pointer;} .docs-return{cursor:pointer;} img{max-width:100%;}';
