(function(){
  // This is a visual preview only. It deliberately uses fixed sample data
  // so the landing page never presents fabricated market data as live.
  var asks = [
    {price: 3216.10, size: 0.82, total: 0.82},
    {price: 3215.74, size: 1.14, total: 1.96},
    {price: 3215.31, size: 0.56, total: 2.52},
    {price: 3214.98, size: 0.91, total: 3.43},
    {price: 3214.62, size: 1.32, total: 4.75},
    {price: 3214.40, size: 0.67, total: 5.42}
  ];
  var bids = [
    {price: 3214.12, size: 0.71, total: 0.71},
    {price: 3213.86, size: 1.08, total: 1.79},
    {price: 3213.47, size: 0.64, total: 2.43},
    {price: 3213.05, size: 1.25, total: 3.68},
    {price: 3212.69, size: 0.83, total: 4.51},
    {price: 3212.31, size: 1.17, total: 5.68}
  ];
  var maxTotal = Math.max(asks[asks.length - 1].total, bids[bids.length - 1].total);
  function renderRows(rows, cls, priceCls) {
    var fragment = document.createDocumentFragment();
    rows.forEach(function(r){
      var pct = Math.min(100, (r.total / maxTotal) * 100);
      var row = document.createElement('div');
      row.className = 'row ' + cls;

      var depth = document.createElement('span');
      depth.className = 'depth';
      depth.style.width = pct + '%';

      var price = document.createElement('span');
      price.className = 'mono ' + priceCls;
      price.textContent = r.price.toFixed(2);

      var size = document.createElement('span');
      size.className = 'mono size';
      size.textContent = r.size.toFixed(3);

      var total = document.createElement('span');
      total.className = 'mono total';
      total.textContent = r.total.toFixed(2);

      row.appendChild(depth);
      row.appendChild(price);
      row.appendChild(size);
      row.appendChild(total);
      fragment.appendChild(row);
    });
    return fragment;
  }
  var asksEl = document.getElementById('asks');
  var bidsEl = document.getElementById('bids');
  if (!asksEl || !bidsEl) return;
  asksEl.replaceChildren(renderRows(asks.slice().reverse(), 'ask', 'ask-price'));
  bidsEl.replaceChildren(renderRows(bids, 'bid', 'bid-price'));
  document.getElementById('mid-price').textContent = '3,214.26';
  document.getElementById('spread-val').textContent = '0.28 (0.009%)';
})();

