(function(){
  const toggle = document.querySelector('.vq-mobile-toggle');
  const menu = document.getElementById('vq-mobile-menu');
  if(!toggle || !menu) return;
  function closeMenu(){
    menu.hidden = true;
    toggle.setAttribute('aria-expanded','false');
    toggle.querySelector('.sr-only').textContent = 'Open navigation';
  }
  function openMenu(){
    menu.hidden = false;
    toggle.setAttribute('aria-expanded','true');
    toggle.querySelector('.sr-only').textContent = 'Close navigation';
    const first = menu.querySelector('a');
    if(first) first.focus();
  }
  toggle.addEventListener('click', function(){
    menu.hidden ? openMenu() : closeMenu();
  });
  menu.addEventListener('click', function(e){
    if(e.target.closest('a')) closeMenu();
  });
  document.addEventListener('keydown', function(e){
    if(e.key === 'Escape' && !menu.hidden){
      closeMenu();
      toggle.focus();
    }
  });
})();

