(function(){
'use strict';
// Make interactive controls feel immediate without changing the underlying product logic.
document.addEventListener('click',function(e){
  var el=e.target.closest('a,button,.btn,[role="button"]');
  if(!el||el.getAttribute('aria-disabled')==='true'||el.disabled)return;
  el.classList.add('vq-pressed');setTimeout(function(){el.classList.remove('vq-pressed')},180);
},true);
// Give external/launch actions a subtle pending state instead of a dead-feeling click.
document.addEventListener('click',function(e){
  var el=e.target.closest('a[href]');
  if(!el||el.target==='_blank'||el.href.indexOf('#')===el.href.length-1)return;
  if(el.dataset.vqBusy)return;
  el.dataset.vqBusy='1';
  setTimeout(function(){delete el.dataset.vqBusy},900);
},true);
// Keep keyboard users informed when a control is activated.
document.addEventListener('keydown',function(e){
  if((e.key==='Enter'||e.key===' ')&&e.target.matches('button,[role="button"]'))e.target.classList.add('vq-keypress');
});
document.addEventListener('keyup',function(e){e.target.classList.remove('vq-keypress')});
})();

