(function(){
  // Give demo orderbook levels useful, keyboard-accessible feedback without
  // pretending the static preview is live market data.
  var rows=document.querySelectorAll('#book .row');
  rows.forEach(function(row,index){
    row.setAttribute('tabindex','0');
    row.setAttribute('role','button');
    var price=row.querySelector('.mono');
    var label=price ? price.textContent.trim() : ('level '+(index+1));
    row.setAttribute('aria-label','Select price level '+label);
    function select(){
      rows.forEach(function(r){r.classList.remove('vq-selected');});
      row.classList.add('vq-selected');
    }
    row.addEventListener('click',select);
    row.addEventListener('keydown',function(e){
      if(e.key==='Enter' || e.key===' '){e.preventDefault();select();}
    });
  });

  // Show the mobile CTA only after the hero CTA has scrolled away.
  var sticky=document.querySelector('.vq-mobile-sticky');
  var heroActions=document.querySelector('.hero .hero-actions');
  if(!sticky || !heroActions || !('IntersectionObserver' in window)) return;
  var observer=new IntersectionObserver(function(entries){
    var visible=entries[0].isIntersecting;
    sticky.classList.toggle('vq-visible',!visible);
    document.body.classList.toggle('vq-sticky-visible',!visible);
  },{threshold:0.05});
  observer.observe(heroActions);
})();

